   626				const relationshipIds = ledger.relationships.map((item) => item.id);
   627				const currentRelationships =
   628					relationshipIds.length > 0
   629						? await tx<{
   630								id: number;
   631								from_entity_id: number;
   632								to_entity_id: number;
   633								deleted_at: Date | string | null;
   634							}>`
   635	            SELECT id, from_entity_id, to_entity_id, deleted_at
   636	            FROM entity_relationships
   637	            WHERE organization_id = ${orgId}
   638	              AND id = ANY(${pgBigintArray(relationshipIds)}::bigint[])
   639	            ORDER BY id
   640	            FOR UPDATE
   641	          `
   642						: [];
   643				const currentById = new Map(
   644					currentRelationships.map((row) => [Number(row.id), row]),
   645				);
   646				for (const item of ledger.relationships) {
   647					const current = currentById.get(item.id);
   648					const currentDeletedAt =
   649						current?.deleted_at == null
   650							? null
   651							: new Date(current.deleted_at).toISOString();
   652					if (
   653						!current ||
   654						Number(current.from_entity_id) !== item.after.fromEntityId ||
   655						Number(current.to_entity_id) !== item.after.toEntityId ||
   656						currentDeletedAt !== item.after.deletedAt
   657					) {
   658						throw new Error(
   659							`applyUnmerge: relationship ${item.id} changed after this merge; exact undo is unsafe`,
   660						);
   661					}
   662				}
   663	
   664				for (const item of ledger.relationships) {
   665					await tx`
   666	          UPDATE entity_relationships
   667	          SET from_entity_id = ${item.before.fromEntityId},
   668	              to_entity_id = ${item.before.toEntityId},
   669	              deleted_at = ${item.before.deletedAt},
   670	              updated_at = current_timestamp
   671	          WHERE organization_id = ${orgId} AND id = ${item.id}
   672	        `;
   673				}
   674				const redirectedEntityIds = ledger.redirectedEntityIds ?? [];
   675				if (redirectedEntityIds.length > 0) {
   676					const restoredRedirects = await tx<{ id: number }>`
   677	          UPDATE entities
   678	          SET merged_into = ${loserId}, updated_at = current_timestamp
   679	          WHERE organization_id = ${orgId}
   680	            AND id = ANY(${pgBigintArray(redirectedEntityIds)}::bigint[])
   681	            AND merged_into = ${winnerId}
   682	          RETURNING id
   683	        `;
   684					if (restoredRedirects.length !== redirectedEntityIds.length) {
   685						throw new Error(
   686							"applyUnmerge: a flattened redirect changed after this merge; exact undo is unsafe",
   687						);
   688					}
   689				}
   690				await tx`

