   179	  sql: DbClient,
   180	  organizationId: string,
   181	  memberEntityId: number,
   182	): Promise<Set<string>> {
   183	  if (CHANNEL_KEY_NAMESPACES.length === 0) return new Set();
   184	  const rows = await sql<{ channel_key: string }>`
