   240	  const enforcingTenants: EnforcingTenant[] = [];
   241	  for (const r of rows) {
   242	    if (states.get(r.id)?.status !== "enforced" || !r.team_id) continue;
   243	    const dedupe = `${r.platform}\u0000${r.team_id}`;
   244	    if (seenTenant.has(dedupe)) continue;
   245	    seenTenant.add(dedupe);
