   249	    ? await resolveRequesterMember(sql, organizationId, userId, enforcingTenants)
   250	    : null;
   251	  const visibleKeys =
   252	    memberEntityId === null
   253	      ? new Set<string>()
   254	      : await getVisibleChannelKeysForMember(sql, organizationId, memberEntityId);
   255	
   256	  return rows.filter((r) => {
   257	    const state = states.get(r.id);
   258	    if (!state) return allowNotGraphed; // never graphed → optional legacy fence
   259	    if (state.status !== "enforced") return false; // stale/unsupported → fail closed
   260	    const key = rowToChannelKey(r);
   261	    if (key === null) return false; // no team id → can't form the key → fail closed
   262	    return visibleKeys.has(key);
   263	  });
   264	}

